-- Rebanho: marketing evangelístico.
-- Microáreas (base pública de população por bairro), campanhas da igreja
-- e a ligação de cada visitante com a campanha que o trouxe.

-- ---------------------------------------------------------------- microáreas
-- Dado de referência, igual para todas as igrejas: qualquer usuário logado lê, ninguém altera pela API.
create table microareas (
  id                serial primary key,
  microarea         text not null,
  municipio         text not null,
  uf                char(2) not null,
  cresc_pop_aa      numeric(6,2) not null,
  cresc_renda_aa    numeric(6,2) not null,
  area_km2          numeric(12,2) not null,
  populacao         integer not null,
  densidade         numeric(12,1) not null,
  domicilios        integer not null,
  renda_media       numeric(12,2) not null,
  pea_dia           integer not null,
  potencial_consumo bigint not null,
  unique (uf, municipio, microarea)
);
create index on microareas (uf, municipio);
alter table microareas enable row level security;
create policy micro_ver on microareas for select to authenticated using (true);
revoke insert, update, delete, truncate on microareas from anon, authenticated;

-- ---------------------------------------------------------------- campanhas
create table campanhas (
  id          uuid primary key default gen_random_uuid(),
  igreja_id   uuid not null references igrejas(id) on delete cascade,
  titulo      text not null check (length(trim(titulo)) between 3 and 120),
  microarea   text,
  municipio   text,
  uf          char(2),
  perfil      text not null default 'misto'
              check (perfil in ('polo', 'expansao', 'social', 'alta', 'dormitorio', 'rural', 'misto')),
  inicio      date,
  fim         date,
  meta        integer not null default 0 check (meta >= 0),
  orcamento   numeric(12,2) not null default 0 check (orcamento >= 0),
  status      text not null default 'Planejada' check (status in ('Planejada', 'Em andamento', 'Encerrada')),
  responsavel text,
  acoes       text,
  convite     text,
  canais      text[] not null default '{}',
  criado_por  uuid default auth.uid(),
  criado_em   timestamptz not null default now(),
  check (fim is null or inicio is null or fim >= inicio)
);
create index on campanhas (igreja_id, status);
create trigger campanhas_igreja before update on campanhas for each row execute function travar_igreja();
create trigger auditar_campanhas after insert or update or delete on campanhas
  for each row execute function auditar();

alter table campanhas enable row level security;
create policy camp_ver on campanhas for select
  using (tem_papel(igreja_id, array['pastor','secretaria','lider']::papel_t[]));
create policy camp_criar on campanhas for insert
  with check (tem_papel(igreja_id, array['pastor','secretaria']::papel_t[]));
create policy camp_editar on campanhas for update
  using (tem_papel(igreja_id, array['pastor','secretaria']::papel_t[]));
create policy camp_excluir on campanhas for delete
  using (tem_papel(igreja_id, array['pastor']::papel_t[]));

-- ---------------------------------------------------------------- origem do visitante
alter table pessoas add column campanha_id uuid references campanhas(id) on delete set null;
create index on pessoas (campanha_id) where campanha_id is not null;

create function conferir_campanha() returns trigger language plpgsql as $$
begin
  if new.campanha_id is not null and not exists
     (select 1 from campanhas where id = new.campanha_id and igreja_id = new.igreja_id) then
    raise exception 'A campanha informada não pertence a esta igreja.';
  end if;
  return new;
end $$;
create trigger pessoas_campanha before insert or update of campanha_id on pessoas
  for each row execute function conferir_campanha();

-- Resultado de cada campanha sem expor a ficha das pessoas a quem não pode ver.
create view campanhas_resultado with (security_invoker = true) as
  select c.id, c.igreja_id,
         count(p.id) filter (where not p.anonimizado) as visitantes,
         count(p.id) filter (where not p.anonimizado and p.status in ('congregado', 'membro')) as integrados
    from campanhas c left join pessoas p on p.campanha_id = c.id
   group by c.id, c.igreja_id;

